list_blogs.code:
final response = await client.blogs
    .listBlogs(queryParams: {'visibility': 'open', 'limit': 20});
final blogs = (response.map as Map)['blogs'] as List;
for (final blog in blogs) {
  print('${(blog as Map)['id']} ${blog['title']} ${blog['date']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print('${pagination['total']} ${pagination['has_next']}');

